//! Cargo compatibility projection for MGC-owned Rust artifacts.
//! Projection Cargo chỉ để toolchain đọc artifact Rust do MGC quản lý.

use std::collections::{BTreeMap, BTreeSet, VecDeque};
use std::path::{Path, PathBuf};

use mgc_lockfile::{EcosystemTag, Lockfile, Package};
use mgc_types::{MgError, MgResult};
use serde::Serialize;

const CARGO_LOCK_HEADER: &str =
    "# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\n";
const CARGO_LOCK_VERSION: i64 = 4;
const CRATES_IO_SOURCE: &str = "registry+https://github.com/rust-lang/crates.io-index";

#[derive(Serialize)]
struct CargoLock {
    version: i64,
    package: Vec<CargoPackage>,
}

#[derive(Serialize)]
struct CargoPackage {
    name: String,
    version: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    source: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    checksum: Option<String>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    dependencies: Vec<String>,
}

#[derive(Serialize)]
struct CargoChecksum<'a> {
    files: BTreeMap<String, String>,
    package: &'a str,
}

/// Write Cargo's directory-source checksum after MGC has verified and extracted a crate.
/// Ghi checksum cho Cargo directory source sau khi MGC đã xác minh và giải nén crate.
pub(crate) fn write_source_checksum(
    package_root: &Path,
    package_sha256: &str,
    archive_bytes: &[u8],
) -> MgResult<()> {
    use sha2::{Digest, Sha256};

    validate_sha256(package_sha256)?;
    let archive_sha256 = hex::encode(Sha256::digest(archive_bytes));
    if !archive_sha256.eq_ignore_ascii_case(package_sha256) {
        return Err(MgError::Integrity(
            "Cargo crate archive digest changed before source projection".to_string(),
        ));
    }
    let expected_root = package_root
        .file_name()
        .and_then(|value| value.to_str())
        .ok_or_else(|| MgError::Other("Cargo source package path is invalid".to_string()))?;
    let files =
        mgc_resolver::protocols::archive::cargo_source_file_hashes(archive_bytes, expected_root)
            .map_err(|error| MgError::Integrity(error.to_string()))?;
    if hash_source_files(package_root)? != files {
        return Err(MgError::Integrity(
            "extracted Cargo source differs from its verified archive".to_string(),
        ));
    }
    let checksum = CargoChecksum {
        files,
        package: &archive_sha256,
    };
    let bytes = serde_json::to_vec(&checksum)
        .map_err(|error| MgError::Other(format!("serialize Cargo source checksum: {error}")))?;
    atomic_write(package_root, Path::new(".cargo-checksum.json"), &bytes)
}

/// Refresh Cargo.lock from the canonical MGC lock without asking Cargo to resolve packages.
/// Cập nhật Cargo.lock từ mgc.lock canonical, không giao Cargo tự resolve package.
pub(crate) fn refresh_lock(project_root: &Path) -> MgResult<()> {
    let lock = super::read_existing_lock(project_root)?;
    let rust_packages = rust_packages(&lock)?;
    let bytes = if rust_packages.is_empty() {
        super::prepare_empty_cargo_lock(project_root, &[])?
    } else {
        Some(project_cargo_lock(project_root, &rust_packages)?)
    };
    if let Some(bytes) = bytes {
        super::atomic_write_cargo_lock(project_root, &bytes)?;
    }
    Ok(())
}

/// Refuse unsupported graph shapes before install downloads or writes artifacts.
/// Từ chối graph ngoài phạm vi trước khi install tải hay ghi artifact.
pub(crate) fn validate_install(project_root: &Path, lock_packages: &[Package]) -> MgResult<()> {
    let lock = Lockfile {
        packages: lock_packages.to_vec(),
        ..Lockfile::new()
    };
    let packages = rust_packages(&lock)?;
    if packages.is_empty() {
        let _ = super::prepare_empty_cargo_lock(project_root, lock_packages)?;
        return Ok(());
    }
    let _ = project_cargo_lock(project_root, &packages)?;
    Ok(())
}

/// Validate both lock projections and return MGC's directory source for a Rust build.
/// Xác minh hai lock projection và trả directory source của MGC cho bước build Rust.
pub fn validate_build(project_root: &Path) -> MgResult<Option<PathBuf>> {
    let lock = super::read_existing_lock(project_root)?;
    let rust_packages = rust_packages(&lock)?;
    validate_lib_build_ownership(&rust_packages)?;
    let expected = if rust_packages.is_empty() {
        match super::prepare_empty_cargo_lock(project_root, &[])? {
            // `None` means the existing provider lock is byte-identical to
            // the validated empty projection, so no managed registry source
            // is needed for this dependency-free project.
            // (`None` xác nhận lock hiện tại trùng byte projection rỗng đã
            // kiểm; project không dependency nên không cần source managed.)
            None => return Ok(None),
            Some(bytes) => bytes,
        }
    } else {
        project_cargo_lock(project_root, &rust_packages)?
    };
    let cargo_lock_path = project_root.join("Cargo.lock");
    let actual = mgc_adapter_base::project_file::read_regular_text(&cargo_lock_path, "Cargo.lock")
        .map_err(|error| MgError::Other(format!("cannot verify Cargo.lock projection: {error}")))?;
    let expected_value: toml::Value =
        toml::from_str(std::str::from_utf8(&expected).map_err(|error| {
            MgError::Other(format!("generated Cargo.lock is not UTF-8: {error}"))
        })?)
        .map_err(|error| MgError::Other(format!("parse generated Cargo.lock: {error}")))?;
    let actual_value: toml::Value = toml::from_str(&actual)
        .map_err(|error| MgError::Other(format!("Cargo.lock is not valid TOML: {error}")))?;
    if actual_value != expected_value {
        return Err(MgError::Other(
            "Cargo.lock does not match the MGC dependency graph; run `mgc install-lib`".to_string(),
        ));
    }
    if rust_packages.is_empty() {
        return Ok(None);
    }

    let store = mgc_platform::paths::GlobalPaths::new()
        .map_err(|error| MgError::Other(format!("cannot resolve MGC store: {error}")))?
        .store;
    let source_root = store.join("cargo").join("registry").join("src");
    for package in &rust_packages {
        let source_dir = source_root.join(format!("{}-{}", package.name, package.version));
        let metadata = std::fs::symlink_metadata(&source_dir).map_err(|error| {
            MgError::Other(format!(
                "managed Cargo source is missing for '{}'@{}: {error}; run `mgc install-lib`",
                package.name, package.version
            ))
        })?;
        if !metadata.is_dir() || metadata.file_type().is_symlink() {
            return Err(MgError::Other(format!(
                "managed Cargo source is not a regular directory for '{}'@{}",
                package.name, package.version
            )));
        }
        let expected_sha256 = mgc_lockfile::policy::native_sha256_hex(&package.integrity);
        let expected_sha256 = expected_sha256.as_str();
        let archive_path = source_root
            .parent()
            .ok_or_else(|| MgError::Other("Cargo source registry path is invalid".to_string()))?
            .join("cache")
            .join(format!("{}-{}.crate", package.name, package.version));
        let archive = super::read_cached_rust_artifact(&archive_path, expected_sha256)?
            .ok_or_else(|| {
                MgError::Other(format!(
                    "managed Cargo archive is missing for '{}'@{}",
                    package.name, package.version
                ))
            })?;
        verify_source_checksum(&source_dir, expected_sha256, &archive)
        .map_err(|error| {
            MgError::Other(format!(
                "managed Cargo source verification failed for '{}'@{}: {error}; run `mgc install-lib`",
                package.name, package.version
            ))
        })?;
    }
    Ok(Some(source_root))
}

fn rust_packages(lock: &Lockfile) -> MgResult<Vec<&Package>> {
    let mut packages = lock
        .packages
        .iter()
        .filter(|package| package.ecosystem == EcosystemTag::Rust)
        .collect::<Vec<_>>();
    packages.sort_by(|left, right| (&left.name, &left.version).cmp(&(&right.name, &right.version)));
    let mut identities = BTreeSet::new();
    let mut names = BTreeSet::new();
    for package in &packages {
        mgc_types::PackageName::new(package.name.clone()).map_err(|_| {
            MgError::Other(format!(
                "Cargo build refuses invalid locked crate name '{}'",
                package.name
            ))
        })?;
        mgc_types::Version::parse(&package.version).map_err(|error| {
            MgError::Other(format!(
                "Cargo build refuses invalid locked version '{}': {error}",
                package.version
            ))
        })?;
        let identity = (package.name.as_str(), package.version.as_str());
        if !identities.insert(identity) {
            return Err(MgError::Other(format!(
                "Cargo projection refuses duplicate locked package '{}@{}'",
                package.name, package.version
            )));
        }
        if !names.insert(package.name.as_str()) {
            return Err(MgError::Other(format!(
                "Cargo projection cannot represent multiple locked versions of '{}' yet",
                package.name
            )));
        }
        // The crates.io resolver records feature-optional and target-qualified
        // edges while keeping their package names in the complete Cargo lock
        // closure. Reject unknown marker types, which cannot be projected
        // without interpreting undocumented resolver metadata.
        // (Resolver crates.io giữ cạnh optional/target trong Cargo lock closure
        // đầy đủ. Từ chối kiểu marker lạ vì chưa có quy tắc projection.)
        let unsupported_marker = package.markers.as_ref().and_then(|values| {
            values
                .iter()
                .find(|marker| !is_cargo_dependency_edge_marker(marker))
        });
        if let Some(marker) = unsupported_marker {
            return Err(MgError::Other(format!(
                "Cargo projection cannot represent marker '{marker}' for '{}'@{} yet",
                package.name, package.version,
            )));
        }
        if package
            .extras
            .as_ref()
            .is_some_and(|values| !values.is_empty())
        {
            return Err(MgError::Other(format!(
                "Cargo projection cannot represent feature variants for '{}'@{} yet",
                package.name, package.version
            )));
        }
        validate_sha256(&mgc_lockfile::policy::native_sha256_hex(&package.integrity))?;
        if package.registry.as_deref().is_none_or(|registry| {
            !matches!(
                registry,
                "crates://crates.io" | "crates://sparse+https://index.crates.io"
            )
        }) {
            return Err(MgError::Other(format!(
                "Cargo projection currently supports only crates.io source identity ('{}@{}')",
                package.name, package.version
            )));
        }
    }
    Ok(packages)
}

fn validate_lib_build_ownership(packages: &[&Package]) -> MgResult<()> {
    for package in packages {
        if package
            .owner_core
            .as_deref()
            .is_some_and(|owner| owner != "lib")
        {
            return Err(MgError::Other(format!(
                "Cargo library build cannot consume Rust package '{}' owned by core '{}'",
                package.name,
                package.owner_core.as_deref().unwrap_or_default()
            )));
        }
    }
    Ok(())
}

/// Accept only resolver marker forms whose dependency remains in the exact
/// Cargo lock closure: a valid optional crate name or a non-empty target cfg.
/// Chấp nhận marker chỉ khi dependency vẫn nằm trong Cargo lock closure:
/// optional crate hợp lệ hoặc target cfg không rỗng.
fn is_cargo_dependency_edge_marker(marker: &str) -> bool {
    if let Some(name) = marker.strip_prefix("optional:") {
        return !name.is_empty() && mgc_types::PackageName::new(name.to_string()).is_ok();
    }
    marker
        .strip_prefix("target:")
        .is_some_and(|target| !target.trim().is_empty())
}

fn project_cargo_lock(project_root: &Path, packages: &[&Package]) -> MgResult<Vec<u8>> {
    let manifest_path = project_root.join("Cargo.toml");
    let manifest = mgc_adapter_base::project_file::read_regular_text(&manifest_path, "Cargo.toml")?;
    let manifest: toml::Value = toml::from_str(&manifest).map_err(|error| {
        MgError::Other(format!("parse Cargo.toml for Cargo projection: {error}"))
    })?;
    let package_table = manifest
        .get("package")
        .and_then(toml::Value::as_table)
        .ok_or_else(|| {
            MgError::Other("Cargo projection requires a package manifest".to_string())
        })?;
    if package_table.contains_key("workspace") {
        return Err(MgError::Other(
            "Cargo projection does not support workspace-inherited package metadata yet"
                .to_string(),
        ));
    }
    if let Some(workspace) = manifest.get("workspace").and_then(toml::Value::as_table)
        && ["members", "default-members"].iter().any(|key| {
            workspace
                .get(*key)
                .and_then(toml::Value::as_array)
                .is_some_and(|members| !members.is_empty())
        })
    {
        return Err(MgError::Other(
            "Cargo projection does not support workspaces yet".to_string(),
        ));
    }
    for section in [
        "dev-dependencies",
        "build-dependencies",
        "target",
        "patch",
        "replace",
    ] {
        if manifest
            .get(section)
            .is_some_and(|value| value.as_table().is_none_or(|table| !table.is_empty()))
        {
            return Err(MgError::Other(format!(
                "Cargo projection does not support Cargo.toml [{section}] yet"
            )));
        }
    }
    if manifest
        .get("features")
        .and_then(toml::Value::as_table)
        .is_some_and(|features| !features.is_empty())
    {
        return Err(MgError::Other(
            "Cargo projection does not support custom root features yet".to_string(),
        ));
    }
    let root_name = required_string(package_table, "name", "Cargo.toml package.name")?;
    let root_version = required_string(package_table, "version", "Cargo.toml package.version")?;
    mgc_types::Version::parse(root_version)
        .map_err(|error| MgError::Other(format!("invalid Cargo.toml package.version: {error}")))?;

    let mut by_name = BTreeMap::<&str, &Package>::new();
    for package in packages {
        by_name.insert(package.name.as_str(), package);
    }
    if by_name.contains_key(root_name) {
        return Err(MgError::Other(
            "Cargo root package name collides with a registry package".to_string(),
        ));
    }
    let mut roots = Vec::new();
    if let Some(dependencies) = manifest.get("dependencies") {
        let dependencies = dependencies.as_table().ok_or_else(|| {
            MgError::Other("Cargo.toml [dependencies] must be a table".to_string())
        })?;
        for (name, spec) in dependencies {
            if !spec.is_str() {
                return Err(MgError::Other(format!(
                    "Cargo projection supports only plain version strings for dependency '{name}'"
                )));
            }
            if !by_name.contains_key(name.as_str()) {
                return Err(MgError::Other(format!(
                    "Cargo dependency '{name}' is absent from mgc.lock; run `mgc install-lib`"
                )));
            }
            roots.push(name.clone());
        }
    }
    roots.sort();

    let mut reachable = BTreeSet::<String>::new();
    let mut pending = VecDeque::from(roots.clone());
    while let Some(name) = pending.pop_front() {
        if !reachable.insert(name.clone()) {
            continue;
        }
        let package = by_name.get(name.as_str()).ok_or_else(|| {
            MgError::Other(format!(
                "mgc.lock dependency '{name}' is not present in its package table"
            ))
        })?;
        for dependency in &package.dependencies {
            if !by_name.contains_key(dependency.as_str()) {
                return Err(MgError::Other(format!(
                    "mgc.lock package '{}'@{} references missing dependency '{dependency}'",
                    package.name, package.version
                )));
            }
            pending.push_back(dependency.clone());
        }
    }
    if reachable.len() != packages.len() {
        return Err(MgError::Other(
            "mgc.lock contains Rust packages unreachable from Cargo.toml roots".to_string(),
        ));
    }

    let mut rows = Vec::with_capacity(packages.len() + 1);
    rows.push(CargoPackage {
        name: root_name.to_string(),
        version: root_version.to_string(),
        source: None,
        checksum: None,
        dependencies: roots,
    });
    for package in packages {
        let mut dependencies = package.dependencies.clone();
        dependencies.sort();
        dependencies.dedup();
        rows.push(CargoPackage {
            name: package.name.clone(),
            version: package.version.clone(),
            source: Some(CRATES_IO_SOURCE.to_string()),
            checksum: Some(mgc_lockfile::policy::native_sha256_hex(&package.integrity)),
            dependencies,
        });
    }
    rows.sort_by(|left, right| {
        (&left.name, &left.version, &left.source).cmp(&(&right.name, &right.version, &right.source))
    });
    let document = CargoLock {
        version: CARGO_LOCK_VERSION,
        package: rows,
    };
    let serialized = toml::to_string(&document)
        .map_err(|error| MgError::Other(format!("serialize Cargo.lock projection: {error}")))?;
    let mut bytes = CARGO_LOCK_HEADER.as_bytes().to_vec();
    bytes.extend_from_slice(serialized.as_bytes());
    Ok(bytes)
}

fn required_string<'a>(table: &'a toml::value::Table, key: &str, label: &str) -> MgResult<&'a str> {
    table
        .get(key)
        .and_then(toml::Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| MgError::Other(format!("{label} is required for Cargo projection")))
}

fn validate_sha256(value: &str) -> MgResult<()> {
    if value.len() != 64 || !value.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return Err(MgError::Other(
            "Cargo projection requires a 64-digit SHA-256 package checksum".to_string(),
        ));
    }
    Ok(())
}

fn verify_source_checksum(
    package_root: &Path,
    expected_package_sha256: &str,
    archive_bytes: &[u8],
) -> MgResult<()> {
    validate_sha256(expected_package_sha256)?;
    use sha2::{Digest, Sha256};
    let archive_sha256 = hex::encode(Sha256::digest(archive_bytes));
    if !archive_sha256.eq_ignore_ascii_case(expected_package_sha256) {
        return Err(MgError::Integrity(
            "Cargo crate archive digest differs from the MGC lock".to_string(),
        ));
    }
    let expected_root = package_root
        .file_name()
        .and_then(|value| value.to_str())
        .ok_or_else(|| MgError::Other("Cargo source package path is invalid".to_string()))?;
    let expected_files =
        mgc_resolver::protocols::archive::cargo_source_file_hashes(archive_bytes, expected_root)
            .map_err(|error| MgError::Integrity(error.to_string()))?;
    let checksum_path = package_root.join(".cargo-checksum.json");
    let checksum_text =
        mgc_adapter_base::project_file::read_regular_text(&checksum_path, ".cargo-checksum.json")?;
    let checksum: serde_json::Value = serde_json::from_str(&checksum_text)
        .map_err(|error| MgError::Other(format!("invalid Cargo source checksum: {error}")))?;
    if checksum.get("package").and_then(serde_json::Value::as_str) != Some(archive_sha256.as_str())
    {
        return Err(MgError::Other(
            "package digest differs from the MGC lock".to_string(),
        ));
    }
    let listed_files = checksum
        .get("files")
        .and_then(serde_json::Value::as_object)
        .ok_or_else(|| MgError::Other("Cargo checksum has no files map".to_string()))?
        .iter()
        .map(|(path, digest)| {
            digest
                .as_str()
                .map(|digest| (path.clone(), digest.to_string()))
                .ok_or_else(|| {
                    MgError::Other("Cargo checksum file digest is not a string".to_string())
                })
        })
        .collect::<MgResult<BTreeMap<_, _>>>()?;
    let actual_files = hash_source_files(package_root)?;
    if listed_files != expected_files || actual_files != expected_files {
        return Err(MgError::Other(
            "extracted package files differ from the MGC-verified source record".to_string(),
        ));
    }
    Ok(())
}

fn hash_source_files(root: &Path) -> MgResult<BTreeMap<String, String>> {
    use sha2::{Digest, Sha256};

    let metadata = std::fs::symlink_metadata(root)
        .map_err(|error| MgError::Other(format!("inspect managed Cargo source: {error}")))?;
    if !metadata.is_dir() || metadata.file_type().is_symlink() {
        return Err(MgError::Other(
            "managed Cargo source must be a regular directory".to_string(),
        ));
    }
    let mut pending = vec![root.to_path_buf()];
    let mut files = BTreeMap::new();
    while let Some(directory) = pending.pop() {
        let mut entries = std::fs::read_dir(&directory)
            .map_err(|error| MgError::Other(format!("read managed Cargo source: {error}")))?
            .collect::<Result<Vec<_>, _>>()
            .map_err(|error| MgError::Other(format!("read managed Cargo source entry: {error}")))?;
        entries.sort_by_key(|entry| entry.file_name());
        for entry in entries {
            if entry.file_name() == ".cargo-checksum.json" {
                continue;
            }
            let path = entry.path();
            let metadata = std::fs::symlink_metadata(&path)
                .map_err(|error| MgError::Other(format!("inspect managed Cargo file: {error}")))?;
            if metadata.file_type().is_symlink() {
                return Err(MgError::Other(format!(
                    "managed Cargo source contains a symbolic link: {}",
                    path.display()
                )));
            }
            if metadata.is_dir() {
                pending.push(path);
                continue;
            }
            if !metadata.is_file() {
                return Err(MgError::Other(format!(
                    "managed Cargo source contains a special file: {}",
                    path.display()
                )));
            }
            let relative = path.strip_prefix(root).map_err(|error| {
                MgError::Other(format!(
                    "managed Cargo path escapes source directory: {error}"
                ))
            })?;
            let mut parts = Vec::new();
            for component in relative.components() {
                let std::path::Component::Normal(part) = component else {
                    return Err(MgError::Other(
                        "managed Cargo source path has an unsafe component".to_string(),
                    ));
                };
                parts.push(part.to_str().ok_or_else(|| {
                    MgError::Other("managed Cargo source path is not UTF-8".to_string())
                })?);
            }
            let contents = std::fs::read(&path)
                .map_err(|error| MgError::Other(format!("read managed Cargo file: {error}")))?;
            files.insert(parts.join("/"), hex::encode(Sha256::digest(contents)));
        }
    }
    Ok(files)
}

fn atomic_write(directory: &Path, relative: &Path, bytes: &[u8]) -> MgResult<()> {
    use std::io::Write;
    use std::sync::atomic::{AtomicU64, Ordering};

    static NEXT_TEMP: AtomicU64 = AtomicU64::new(0);
    let destination = directory.join(relative);
    match std::fs::symlink_metadata(&destination) {
        Ok(metadata) if metadata.file_type().is_file() => {
            let current =
                mgc_adapter_base::project_file::read_regular_text(&destination, "checksum")?;
            if current.as_bytes() == bytes {
                return Ok(());
            }
        }
        Ok(_) => {
            return Err(MgError::Other(format!(
                "refusing non-regular managed Cargo checksum '{}'",
                destination.display()
            )));
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => {
            return Err(MgError::Other(format!(
                "inspect checksum destination: {error}"
            )));
        }
    }
    let sequence = NEXT_TEMP.fetch_add(1, Ordering::Relaxed);
    let temp = directory.join(format!(
        ".cargo-checksum.{}.{}.tmp",
        std::process::id(),
        sequence
    ));
    let result = (|| {
        let mut options = std::fs::OpenOptions::new();
        options.write(true).create_new(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt;
            options.mode(0o600).custom_flags(libc::O_NOFOLLOW);
        }
        let mut file = options.open(&temp).map_err(|error| {
            MgError::Other(format!("create Cargo checksum staging file: {error}"))
        })?;
        file.write_all(bytes)
            .and_then(|()| file.sync_all())
            .map_err(|error| {
                MgError::Other(format!("write Cargo checksum staging file: {error}"))
            })?;
        match std::fs::symlink_metadata(&destination) {
            Ok(metadata) if metadata.file_type().is_file() => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Ok(_) => {
                return Err(MgError::Other(
                    "refusing linked Cargo checksum destination".to_string(),
                ));
            }
            Err(error) => {
                return Err(MgError::Other(format!(
                    "inspect Cargo checksum destination: {error}"
                )));
            }
        }
        mgc_lockfile::atomic::atomic_replace_file(&temp, &destination).map_err(|error| {
            MgError::Other(format!("replace Cargo checksum atomically: {error}"))
        })?;
        #[cfg(unix)]
        std::fs::File::open(directory)
            .and_then(|parent| parent.sync_all())
            .map_err(|error| MgError::Other(format!("sync Cargo source directory: {error}")))?;
        Ok(())
    })();
    if result.is_err() {
        let _ = std::fs::remove_file(&temp);
    }
    result
}

